"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { AppNav } from "@/components/AppNav";
import { useApp } from "@/context/AppContext";

export default function AppLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const { ready, userId, profile, plan } = useApp();

  useEffect(() => {
    if (!ready) return;
    if (!userId) {
      router.replace("/auth");
      return;
    }
    if (!profile?.privacy_consent_given) {
      router.replace("/privacy-consent");
      return;
    }
    if (!profile?.onboarding_completed) {
      router.replace("/onboarding");
      return;
    }
    if (!plan) {
      router.replace("/generating-plan");
    }
  }, [ready, userId, profile, plan, router]);

  if (!ready) {
    return <div className="p-10 text-[var(--ink-muted)]">Loading…</div>;
  }

  return (
    <div className="min-h-screen pb-24 md:pb-0 md:pt-16">
      <AppNav />
      <div className="mx-auto max-w-3xl px-4 py-6 md:px-6">{children}</div>
    </div>
  );
}

"use client";

import { Suspense, useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Button } from "@/components/Button";
import { useApp } from "@/context/AppContext";
import { OFFERINGS } from "@/services/entitlements";
import type { Entitlement } from "@/types";

function LibraryInner() {
  const params = useSearchParams();
  const selectedId = params.get("dish");
  const { catalog, canViewRecipeSteps, grantLocalEntitlement, trial } = useApp();
  const [activeId, setActiveId] = useState(selectedId || catalog[0]?.dish_id);
  const dish = useMemo(
    () => catalog.find((d) => d.dish_id === activeId) || catalog[0],
    [catalog, activeId]
  );
  const unlocked = dish ? canViewRecipeSteps(dish.dish_id) : false;
  const [status, setStatus] = useState<string | null>(null);

  async function unlockRecipe() {
    if (!dish) return;
    setStatus("Creating Razorpay order…");
    try {
      const res = await fetch("/api/razorpay/create-order", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ offering: "recipe", dishId: dish.dish_id }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Checkout failed");

      // Demo grant when Razorpay keys are absent (local/test without keys)
      if (data.demo) {
        const entitlement: Entitlement = {
          id: `local_${Date.now()}`,
          user_id: "local",
          kind: "recipe_unlock",
          dish_id: dish.dish_id,
          starts_at: new Date().toISOString(),
          ends_at: null,
          source: "demo_checkout",
        };
        grantLocalEntitlement(entitlement);
        setStatus("Recipe unlocked (demo mode).");
        return;
      }

      setStatus(`Order ${data.orderId} created for ₹${OFFERINGS.recipe.amountPaise / 100}. Complete payment in Razorpay Checkout.`);
    } catch (e) {
      setStatus(e instanceof Error ? e.message : "Unlock failed");
    }
  }

  if (!dish) return <p>No dishes in catalog.</p>;

  return (
    <div className="grid gap-6 md:grid-cols-[240px_1fr]">
      <aside className="max-h-[70vh] space-y-2 overflow-y-auto">
        {catalog.map((item) => (
          <button
            key={item.dish_id}
            type="button"
            onClick={() => setActiveId(item.dish_id)}
            className={`block w-full rounded-2xl px-3 py-3 text-left text-sm ${
              item.dish_id === dish.dish_id
                ? "bg-[var(--forest)] text-[var(--cream-soft)]"
                : "bg-white/70 text-[var(--ink)]"
            }`}
          >
            {item.name}
          </button>
        ))}
      </aside>

      <article className="rounded-3xl border border-[var(--forest)]/10 bg-white/70 p-6">
        <p className="text-xs uppercase tracking-wide text-[var(--ink-muted)]">
          {dish.meal_slots.join(" · ")}
        </p>
        <h1 className="mt-2 font-[family-name:var(--font-display)] text-3xl text-[var(--forest)]">
          {dish.name}
        </h1>
        <p className="mt-3 text-[var(--ink-muted)]">{dish.recipe_preview}</p>
        <div className="mt-5">
          <h2 className="font-semibold text-[var(--ink)]">Ingredients</h2>
          <p className="mt-2 text-sm text-[var(--ink-muted)]">
            {dish.ingredients.map((i) => i.replaceAll("_", " ")).join(", ")}
          </p>
        </div>

        <div className="mt-6">
          <h2 className="font-semibold text-[var(--ink)]">Step-by-step</h2>
          {unlocked ? (
            <ol className="mt-3 list-decimal space-y-2 pl-5 text-sm text-[var(--ink-muted)]">
              {(
                dish.recipe_steps?.split("\n").filter(Boolean) || [
                  "Prep ingredients and set out spices.",
                  "Cook according to your preferred heat and texture.",
                  "Plate and enjoy — adjust salt last.",
                ]
              ).map((step) => (
                <li key={step}>{step}</li>
              ))}
            </ol>
          ) : (
            <div className="mt-3 rounded-2xl border border-dashed border-[var(--forest)]/25 bg-[var(--mist)] p-4">
              <p className="text-sm text-[var(--ink-muted)]">
                Full instructions are gated. Trial reason: {trial.reason}. Unlock for ₹99 or subscribe
                to Pro.
              </p>
              <Button className="mt-4" onClick={unlockRecipe}>
                Unlock for ₹99
              </Button>
            </div>
          )}
        </div>
        {status && <p className="mt-4 text-sm text-[var(--ink-muted)]">{status}</p>}
      </article>
    </div>
  );
}

export default function LibraryPage() {
  return (
    <Suspense fallback={<p>Loading library…</p>}>
      <LibraryInner />
    </Suspense>
  );
}

"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { Button } from "@/components/Button";
import { useApp } from "@/context/AppContext";
import type { MealSlot } from "@/types";

export default function PlanPage() {
  const {
    plan,
    profile,
    trial,
    busy,
    swap,
    dislike,
    regenerate,
    logMeal,
    toggleCheat,
    toggleFestive,
    canUsePlanActions,
  } = useApp();
  const [selected, setSelected] = useState(0);
  const [message, setMessage] = useState<string | null>(null);

  const day = plan?.days[selected];
  const locked = !canUsePlanActions();

  const banner = useMemo(() => {
    if (profile?.medical_conditions?.length && !profile.medical_disclaimer_acked) {
      return "Limited plan — medical disclaimer applies.";
    }
    if (trial.reason === "trial" && trial.is_active) {
      return `${trial.days_left} day${trial.days_left === 1 ? "" : "s"} left in your free trial.`;
    }
    if (trial.reason === "expired") {
      return "Trial ended. Upgrade to swap, regenerate, or unlock full recipes.";
    }
    return null;
  }, [profile, trial]);

  async function runAction(action: () => Promise<void>, success: string) {
    try {
      setMessage(null);
      await action();
      setMessage(success);
    } catch (e) {
      setMessage(e instanceof Error ? e.message : "Action failed");
    }
  }

  if (!plan || !day) {
    return <p className="text-[var(--ink-muted)]">Generating your plan…</p>;
  }

  return (
    <div>
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="font-[family-name:var(--font-display)] text-3xl text-[var(--forest)]">
            Your plan
          </h1>
          <p className="mt-1 text-sm text-[var(--ink-muted)]">
            {plan.daily_kcal_target} kcal/day target · {plan.mode} mode
          </p>
        </div>
        {locked && (
          <Link href="/pricing" className="rounded-full bg-[var(--citrus)] px-4 py-2 text-sm font-semibold">
            Upgrade
          </Link>
        )}
      </div>

      {banner && (
        <div className="mt-4 rounded-2xl border border-[var(--forest)]/15 bg-white/70 px-4 py-3 text-sm text-[var(--forest)]">
          {banner}
        </div>
      )}

      <div className="mt-6 flex gap-2 overflow-x-auto pb-1">
        {plan.days.map((d, index) => (
          <button
            key={d.date}
            type="button"
            onClick={() => setSelected(index)}
            className={`min-w-14 rounded-2xl px-3 py-3 text-sm ${
              selected === index
                ? "bg-[var(--forest)] text-[var(--cream-soft)]"
                : "bg-white/70 text-[var(--ink)]"
            }`}
          >
            D{index + 1}
          </button>
        ))}
      </div>

      <div className="mt-4 flex flex-wrap gap-2">
        <Button variant="ghost" disabled={busy} onClick={() => toggleCheat(day.date)}>
          {day.flags.cheat ? "Unmark cheat day" : "Mark cheat day"}
        </Button>
        <Button variant="ghost" disabled={busy} onClick={() => toggleFestive(day.date)}>
          {day.flags.festive ? "Unmark festive" : "Mark festive"}
        </Button>
        <Button
          variant="secondary"
          disabled={busy || locked}
          onClick={() =>
            runAction(() => regenerate(day.date), "Day regenerated")
          }
        >
          Regenerate day
        </Button>
      </div>

      <div className="mt-6 space-y-4">
        {day.meals.map((meal) => (
          <MealCard
            key={meal.slot}
            slot={meal.slot}
            name={meal.name}
            kcal={meal.kcal}
            status={meal.status}
            dishId={meal.dish_id}
            disabled={busy || locked}
            onSwap={() => runAction(() => swap(day.date, meal.slot), "Meal swapped")}
            onDislike={() =>
              runAction(() => dislike(day.date, meal.slot), "We'll avoid this next time")
            }
            onLog={(status) => logMeal(day.date, meal.slot, status)}
          />
        ))}
      </div>

      {message && <p className="mt-4 text-sm text-[var(--ink-muted)]">{message}</p>}
    </div>
  );
}

function MealCard({
  slot,
  name,
  kcal,
  status,
  dishId,
  disabled,
  onSwap,
  onDislike,
  onLog,
}: {
  slot: MealSlot;
  name: string;
  kcal: number;
  status: string;
  dishId: string;
  disabled: boolean;
  onSwap: () => void;
  onDislike: () => void;
  onLog: (status: "ate" | "swapped" | "skipped") => void;
}) {
  return (
    <article className="rounded-3xl border border-[var(--forest)]/10 bg-white/70 p-5">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-xs uppercase tracking-wide text-[var(--ink-muted)]">{slot}</p>
          <h2 className="mt-1 text-xl font-semibold text-[var(--ink)]">{name}</h2>
          <p className="text-sm text-[var(--ink-muted)]">
            {kcal} kcal · {status}
          </p>
        </div>
        <Link href={`/library?dish=${dishId}`} className="text-sm text-[var(--forest)] underline">
          Recipe
        </Link>
      </div>
      <div className="mt-4 flex flex-wrap gap-2">
        <Button variant="ghost" disabled={disabled} onClick={onSwap}>
          Swap
        </Button>
        <Button variant="ghost" disabled={disabled} onClick={onDislike}>
          Don&apos;t like
        </Button>
        <Button variant="secondary" disabled={disabled} onClick={() => onLog("ate")}>
          Ate
        </Button>
        <Button variant="ghost" disabled={disabled} onClick={() => onLog("swapped")}>
          Swapped
        </Button>
        <Button variant="ghost" disabled={disabled} onClick={() => onLog("skipped")}>
          Skipped
        </Button>
      </div>
    </article>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
