import { NextResponse } from "next/server";
import Razorpay from "razorpay";
import { OFFERINGS } from "@/services/entitlements";

type OfferingKey = keyof typeof OFFERINGS;

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const offering = body.offering as OfferingKey;
    const dishId = body.dishId as string | undefined;

    if (!offering || !(offering in OFFERINGS)) {
      return NextResponse.json({ error: "Invalid offering" }, { status: 400 });
    }

    const keyId = process.env.RAZORPAY_KEY_ID;
    const keySecret = process.env.RAZORPAY_KEY_SECRET;

    if (!keyId || !keySecret) {
      return NextResponse.json({
        demo: true,
        offering,
        dishId: dishId || null,
        amount: OFFERINGS[offering].amountPaise,
        currency: "INR",
      });
    }

    const razorpay = new Razorpay({ key_id: keyId, key_secret: keySecret });
    const order = await razorpay.orders.create({
      amount: OFFERINGS[offering].amountPaise,
      currency: "INR",
      receipt: `mm_${offering}_${Date.now()}`,
      notes: {
        offering,
        dish_id: dishId || "",
      },
    });

    return NextResponse.json({
      demo: false,
      orderId: order.id,
      amount: order.amount,
      currency: order.currency,
      keyId,
      offering,
      dishId: dishId || null,
    });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "Failed to create order" },
      { status: 500 }
    );
  }
}

import { createHmac, timingSafeEqual } from "crypto";
import { NextResponse } from "next/server";

/**
 * Razorpay webhook — grants entitlements only after signature verification.
 * Persist to `entitlements` / `payments` tables when Supabase service role is configured.
 */
export async function POST(request: Request) {
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET;
  const body = await request.text();
  const signature = request.headers.get("x-razorpay-signature");

  if (!secret) {
    return NextResponse.json(
      { error: "RAZORPAY_WEBHOOK_SECRET is not configured" },
      { status: 503 }
    );
  }

  if (!signature) {
    return NextResponse.json({ error: "Missing signature" }, { status: 400 });
  }

  const expected = createHmac("sha256", secret).update(body).digest("hex");
  const valid =
    expected.length === signature.length &&
    timingSafeEqual(Buffer.from(expected), Buffer.from(signature));

  if (!valid) {
    return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
  }

  const payload = JSON.parse(body) as {
    event?: string;
    payload?: {
      payment?: {
        entity?: {
          id?: string;
          notes?: { offering?: string; dish_id?: string; user_id?: string };
          amount?: number;
        };
      };
    };
  };

  if (payload.event !== "payment.captured") {
    return NextResponse.json({ ok: true, ignored: true });
  }

  const payment = payload.payload?.payment?.entity;
  const offering = payment?.notes?.offering;
  const dishId = payment?.notes?.dish_id || null;
  const userId = payment?.notes?.user_id || null;

  // Service-role persistence hook (optional until secrets are wired)
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;

  if (serviceKey && supabaseUrl && userId && offering) {
    const startsAt = new Date().toISOString();
    const ends = new Date();
    if (offering === "pro_monthly" || offering === "plan_monthly") ends.setDate(ends.getDate() + 30);
    if (offering === "plan_weekly") ends.setDate(ends.getDate() + 7);

    await fetch(`${supabaseUrl}/rest/v1/payments`, {
      method: "POST",
      headers: {
        apikey: serviceKey,
        Authorization: `Bearer ${serviceKey}`,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
      },
      body: JSON.stringify({
        provider_payment_id: payment?.id,
        user_id: userId,
        offering,
        amount_paise: payment?.amount,
        status: "captured",
      }),
    });

    await fetch(`${supabaseUrl}/rest/v1/entitlements`, {
      method: "POST",
      headers: {
        apikey: serviceKey,
        Authorization: `Bearer ${serviceKey}`,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
      },
      body: JSON.stringify({
        user_id: userId,
        kind: offering === "recipe" ? "recipe_unlock" : offering,
        dish_id: dishId,
        starts_at: startsAt,
        ends_at: offering === "recipe" ? null : ends.toISOString(),
        source: "razorpay_webhook",
      }),
    });
  }

  return NextResponse.json({
    ok: true,
    granted: Boolean(offering),
    offering,
    dishId,
    userId,
  });
}

"use client";

import { FormEvent, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/Button";
import { useApp } from "@/context/AppContext";
import { isSupabaseConfigured } from "@/lib/supabase/config";

export default function AuthPage() {
  const router = useRouter();
  const params = useSearchParams();
  const mode = params.get("mode") === "signup" ? "signup" : "login";
  const { signInLocal, profile } = useApp();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const supabaseReady = useMemo(() => isSupabaseConfigured(), []);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    try {
      if (supabaseReady) {
        const { createClient } = await import("@/lib/supabase/client");
        const supabase = createClient();
        if (mode === "signup") {
          const { error } = await supabase.auth.signUp({ email, password });
          if (error) throw error;
          setMessage("Check your email to confirm, or continue if confirmations are disabled.");
        } else {
          const { error } = await supabase.auth.signInWithPassword({ email, password });
          if (error) throw error;
        }
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (user?.email) {
          signInLocal(user.email);
        }
      } else {
        // Local demo auth until Supabase env is configured on Vercel
        signInLocal(email || "demo@mealmind.app");
      }

      const nextProfile = profile;
      if (!nextProfile?.privacy_consent_given) {
        router.push("/privacy-consent");
      } else if (!nextProfile?.onboarding_completed) {
        router.push("/onboarding");
      } else if (!nextProfile) {
        router.push("/privacy-consent");
      } else {
        router.push("/plan");
      }
    } catch (err) {
      setMessage(err instanceof Error ? err.message : "Authentication failed");
    } finally {
      setLoading(false);
    }
  }

  async function signInWithGoogle() {
    if (!supabaseReady) {
      setMessage("Connect Supabase env vars to enable Google sign-in.");
      return;
    }
    const { createClient } = await import("@/lib/supabase/client");
    const supabase = createClient();
    const origin = window.location.origin;
    await supabase.auth.signInWithOAuth({
      provider: "google",
      options: { redirectTo: `${origin}/privacy-consent` },
    });
  }

  return (
    <div className="mx-auto flex min-h-screen max-w-md flex-col justify-center px-6 py-12">
      <Link href="/" className="mb-8 font-[family-name:var(--font-display)] text-3xl text-[var(--forest)]">
        MealMind
      </Link>
      <h1 className="text-2xl font-semibold text-[var(--ink)]">
        {mode === "signup" ? "Create your account" : "Welcome back"}
      </h1>
      <p className="mt-2 text-sm text-[var(--ink-muted)]">
        Email + Google via Supabase Auth. {supabaseReady ? "Connected." : "Running in local demo mode."}
      </p>

      <form onSubmit={onSubmit} className="mt-8 space-y-4">
        <label className="block text-sm">
          <span className="mb-1 block text-[var(--ink-muted)]">Email</span>
          <input
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full rounded-2xl border border-[var(--forest)]/15 bg-white/70 px-4 py-3 outline-none focus:border-[var(--forest)]"
          />
        </label>
        <label className="block text-sm">
          <span className="mb-1 block text-[var(--ink-muted)]">Password</span>
          <input
            type="password"
            required={supabaseReady}
            minLength={6}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full rounded-2xl border border-[var(--forest)]/15 bg-white/70 px-4 py-3 outline-none focus:border-[var(--forest)]"
          />
        </label>
        <Button type="submit" disabled={loading} className="w-full">
          {loading ? "Working…" : mode === "signup" ? "Sign up" : "Log in"}
        </Button>
      </form>

      <Button type="button" variant="ghost" className="mt-3 w-full" onClick={signInWithGoogle}>
        Continue with Google
      </Button>

      {message && <p className="mt-4 text-sm text-[var(--ink-muted)]">{message}</p>}

      <p className="mt-6 text-sm text-[var(--ink-muted)]">
        {mode === "signup" ? (
          <>
            Already have an account? <Link href="/auth" className="text-[var(--forest)] underline">Log in</Link>
          </>
        ) : (
          <>
            New here? <Link href="/auth?mode=signup" className="text-[var(--forest)] underline">Sign up</Link>
          </>
        )}
      </p>
    </div>
  );
}

